<?php
session_start(); require 'Includes/dbcon.php'; $err='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $fullname=trim($_POST['fullname']??'');$matricno=trim($_POST['matricno']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';
 if($fullname===''||$matricno===''||strlen($password)<8){$err='Complete all fields. Your password must be at least 8 characters.';}
 elseif($password!==$confirm){$err='The passwords do not match.';}
 else{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$con->prepare('INSERT INTO students (fullname, matricno, password) VALUES (?, ?, ?)');$stmt->bind_param('sss',$fullname,$matricno,$hash);if($stmt->execute())$success='Your account has been created. You can now sign in.';else $err=($con->errno===1062)?'That matric number is already registered.':'Registration could not be completed. Please check your details and try again.';}
}
$pageTitle='Student Registration | FountainTest';include 'Includes/header.php';?>
<div class="auth-wrap"><div class="card"><span class="eyebrow">Student access</span><h1 class="h3 mt-2">Create your account</h1><p class="muted mb-4">Use the details provided by your school.</p><?php if($err):?><div class="alert alert-danger"><?=htmlspecialchars($err)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?></div><?php endif;?><form method="post"><div class="mb-3"><label>Full name</label><input name="fullname" required maxlength="255" class="form-control" value="<?=htmlspecialchars($_POST['fullname']??'')?>"></div><div class="mb-3"><label>Matric number</label><input name="matricno" required maxlength="80" class="form-control" value="<?=htmlspecialchars($_POST['matricno']??'')?>"></div><div class="mb-3"><label>Password</label><input name="password" type="password" minlength="8" required class="form-control" autocomplete="new-password"></div><div class="mb-4"><label>Confirm password</label><input name="confirm_password" type="password" minlength="8" required class="form-control" autocomplete="new-password"></div><button name="register" class="btn btn-success w-100">Create account</button></form><div class="text-center mt-4"><a class="link-success fw-bold" href="index.php">← Back to sign in</a></div></div></div><?php include 'Includes/footer.php';?>
